import React, { forwardRef, PropsWithChildren, useContext } from 'react';
import styled from 'styled-components';

import {
  VALUE_FONT_SIZE,
  VALUE_FONT_CSS_TOKEN,
  PADDING,
} from '../constants.js';
import { FontSizeContext } from '../contexts/font-size.context.js';

interface ContentProps {
  color: string;
  gridTemplateRows: string;
}

interface SyledContentProps extends ContentProps {
  primaryFontSize: number;
}

const StyledContent = /* @__PURE__ */ styled('div').attrs<{
  primaryFontSize: number;
}>(({ primaryFontSize }) => ({
  style: { [VALUE_FONT_CSS_TOKEN]: primaryFontSize },
}))<SyledContentProps>(({ color, gridTemplateRows }) => ({
  gridArea: 'content',
  display: 'grid',
  width: '100%',
  height: '100%',
  color,
  fontSize: `calc(${VALUE_FONT_SIZE} * 1px)`,
  gridTemplateColumns: '1fr',
  gridTemplateAreas: `"label"
    "value"
    "trend"`,
  gridTemplateRows,
  gap: PADDING,
  overflow: 'hidden',
}));

export const ContentGrid = forwardRef<
  HTMLDivElement,
  PropsWithChildren<ContentProps>
>(({ color, gridTemplateRows, children }, forwardedRef) => {
  const { fontSize } = useContext(FontSizeContext);

  return (
    <StyledContent
      ref={forwardedRef}
      color={color}
      gridTemplateRows={gridTemplateRows}
      primaryFontSize={fontSize}
      data-testid="single-value-chart-content"
    >
      {children}
    </StyledContent>
  );
});
